using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language arts." },
        new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Code = "CS201", Title = "Data Structures & Algorithms", Description = "Study fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Wright", InstructorBio = "Dr. Wright specializes in algorithm optimization and competitive programming. He earned his PhD from Stanford and previously worked at Google Research.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Code = "CS310", Title = "Database Systems", Description = "Design and implementation of relational databases. Covers SQL, normalization, transaction processing, and query optimization.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez is a database researcher with industry experience at Oracle and Microsoft. She focuses on distributed systems and data integrity.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Code = "CS420", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised learning, neural networks, and model evaluation techniques.", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 5, Code = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Prof. Alan Torres", InstructorBio = "Prof. Torres is an award-winning educator who has taught calculus for over 20 years. He received the University Teaching Excellence Award in 2023.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
