@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses…"
               @bind="SearchTerm" @bind:event="oninput" @onkeyup="ApplyFilters" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="SelectedDepartmentId" @bind:after="ApplyFilters">
            <option value="0">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

@if (_filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in _filteredCourses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td><a href="courses/@course.Id" class="btn btn-outline-primary btn-sm">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

<p class="text-muted">Showing @_filteredCourses.Count of @_totalCourses courses</p>

@code {
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private string SearchTerm { get; set; } = string.Empty;
    private int SelectedDepartmentId { get; set; }
    private List<Department> _departments = [];
    private List<Course> _filteredCourses = [];
    private int _totalCourses;

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetAllDepartments();
        _totalCourses = CatalogService.GetAllCourses().Count;

        if (DepartmentId.HasValue)
            SelectedDepartmentId = DepartmentId.Value;

        ApplyFilters();
    }

    private void ApplyFilters()
    {
        _filteredCourses = CatalogService.SearchCourses(
            SearchTerm,
            SelectedDepartmentId > 0 ? SelectedDepartmentId : null);
    }
}

